import json
import math

def task_func(decimal_value, precision=2):
    try:
        value = float(decimal_value)
    except (TypeError, ValueError) as exc:
        raise ValueError("decimal_value must be a numeric value") from exc

    if not math.isfinite(value):
        raise ValueError("decimal_value must be finite")
    if value < 0:
        raise ValueError("decimal_value must be non-negative")

    if isinstance(precision, bool):
        raise ValueError("precision must be a non-negative integer")
    try:
        prec = int(precision)
    except (TypeError, ValueError) as exc:
        raise ValueError("precision must be a non-negative integer") from exc

    try:
        if float(precision) != prec:
            raise ValueError("precision must be a non-negative integer")
    except (TypeError, ValueError):
        pass

    if prec < 0:
        raise ValueError("precision must be a non-negative integer")

    result = round(math.sqrt(value), prec)
    return json.dumps(result)
